<?php require_once "../config/database.php";require_once "../config/auth.php";require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)$_POST['id'];$status=$conn->real_escape_string($_POST['status']);$conn->query("UPDATE orders SET status='$status' WHERE id=$id");$note='Admin cập nhật trạng thái';$stmt=$conn->prepare("INSERT INTO order_status_history(order_id,status,note) VALUES(?,?,?)");$stmt->bind_param("iss",$id,$status,$note);$stmt->execute();header("Location:orders.php");exit;}$rows=$conn->query("SELECT o.*,u.name customer_name,r.name restaurant_name FROM orders o JOIN users u ON u.id=o.customer_id JOIN restaurants r ON r.id=o.restaurant_id ORDER BY o.id DESC");$statuses=['pending','confirmed','preparing','ready','driver_received','picked_up','delivering','completed','cancelled'];?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Đơn hàng</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Quản lý đơn hàng</h1><table class="table"><tr><th>Mã</th><th>Khách</th><th>Nhà hàng</th><th>Tổng</th><th>Trạng thái</th><th>Cập nhật</th></tr><?php while($o=$rows->fetch_assoc()):?><tr><td><?=$o['order_code']?></td><td><?=htmlspecialchars($o['customer_name'])?></td><td><?=htmlspecialchars($o['restaurant_name'])?></td><td><?=money($o['total'])?></td><td><?=status_text($o['status'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach($statuses as $s):?><option value="<?=$s?>" <?=$s===$o['status']?'selected':''?>><?=status_text($s)?></option><?php endforeach;?></select><button class="btn">Lưu</button></form></td></tr><?php endwhile;?></table></main></body></html>